181	/** Defer an OPEN claim (not in a closed period) until a date after the sheet's today: until the sheet's today
182	 *  reaches it, the claim counts in no total, is not overdue, cannot be settled and a statement leaves it
183	 *  unbound. Every check is made before anything is written, so a refusal writes nothing to the store or the audit. */
184	final class ClaimDeferral {
185	    private ClaimDeferral() {
186	    }
187	
188	    static Claim apply(String id, long cid, String until, String by, ClaimRepository repository, SheetRepository sheets,
189	            PeriodRepository periods, Audit audit, Rollup rollup) throws BadRequestException {
190	        Claim found = repository.find(id, cid);
191	        if (found == null) {
192	            throw new BadRequestException("no such claim");
193	        }
194	        if (!found.status().equals("OPEN")) {
195	            throw new BadRequestException("a " + found.status() + " claim cannot be deferred");
196	        }
197	        String raw = until == null ? "" : until.trim();
198	        if (raw.isEmpty()) {
199	            throw new BadRequestException("give the date to defer the claim until");
200	        }
201	        LocalDate date;
202	        try {
203	            date = LocalDate.parse(raw);
204	        } catch (DateTimeParseException e) {
205	            throw new BadRequestException("the date to defer until must be yyyy-mm-dd");
206	        }
207	        if (!date.isAfter(sheets.today(id))) {
208	            throw new BadRequestException("a claim can be deferred only to a date after today");
209	        }
210	        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
211	        Rollup.Snapshot before = rollup.take(id);
212	        if (!repository.defer(id, cid, date)) {
213	            throw new BadRequestException("a " + found.status() + " claim cannot be deferred");
214	        }
215	        audit.record("CLAIM_DEFERRED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
216	                + " amount=" + found.amount() + " date=" + found.date() + Claim.auditNumber(found.number())
217	                + " until=" + date);
218	        rollup.record(id, by, before);
219	        return repository.find(id, cid);
220	    }
221	}
