230	    private static final Pattern SIGNED = Pattern.compile("-?(\\d+(\\.\\d{1,2})?|\\.\\d{1,2})");
231	
232	    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?|\\.\\d{1,2}");
233	
234	    /** A typed amount (trimmed): required, a number with up to two decimals, 0.00 or more. */
235	    public static BigDecimal amount(String amount) throws BadRequestException {
