248	        if (amount.isEmpty()) {
249	            throw new BadRequestException("amount is required");
250	        }
251	        if (!SIGNED.matcher(amount).matches()) {
252	            throw new BadRequestException("amount must be a number with up to two decimals");
253	        }
254	        return new BigDecimal(amount).setScale(2);
255	    }
256	
257	    /** Whether the amount is a correction's: below zero. */
258	    public boolean correction() {
259	        return amount.signum() < 0;
260	    }
261	
262	    /** Check the form against the person's claims: a negative amount must name, by number, a SETTLED
263	     *  claim of the same person; only a negative amount may name one. */
264	    public void checkCorrection(ClaimRepository repository, String sheetId, long personId) throws BadRequestException {
265	        if (!correction()) {
266	            if (corrects != null) {
267	                throw new BadRequestException("only a negative amount corrects a claim");
268	            }
269	            return;
270	        }
271	        if (corrects == null) {
272	            throw new BadRequestException("a negative amount is a correction: name the settled claim it corrects");
273	        }
274	        if (!repository.settledOf(sheetId, personId, corrects)) {
275	            throw new BadRequestException("claim " + corrects + " is not a settled claim of this person");
276	        }
277	    }
