699	        // Only a steward approves or rejects a PENDING claim, and never one they opened themselves.
700	        if (found.status().equals("PENDING") && !to.equals("VOID")) {
701	            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
702	                throw new BadRequestException("only a steward can " + action.trim() + " a pending claim");
703	            }
704	            if (to.equals("SETTLED") && by.equals(found.openedBy())) {
705	                throw new BadRequestException("the user who opened a claim cannot approve it");
706	            }
707	        }
