709	        if (event.equals("CLAIM_REJECTED") && why.isEmpty()) {
710	            throw new BadRequestException("give a reason to reject the claim");
711	        }
712	        // A clerk settles outright only a claim whose due is within the sheet's clerk limit ('n/a' is within
713	        // any); above it the claim goes to PENDING for a steward to approve or reject. A steward settles anything.
714	        if (to.equals("SETTLED") && found.status().equals("OPEN")
715	                && settings.role(id, by).equals(SettingsRepository.CLERK)) {
716	            BigDecimal limit = settings.clerkLimit(id);
717	            BigDecimal now = repository.dueNow(id, found);
718	            if (limit != null && now != null && now.compareTo(limit) > 0) {
719	                to = "PENDING";
720	                event = "CLAIM_PENDING";
721	            }
722	        }
