724	        if (!repository.changeStatus(id, cid, from, to)) {
725	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
726	        }
727	        // Opening gives the sheet's next number; a rejected claim keeps its own; a voided claim keeps the number it had (never reused).
728	        String number = found.number();
729	        String openedBy = found.openedBy();
730	        if (found.status().equals("DRAFT") && to.equals("OPEN")) {
731	            number = repository.numbersPerPeriod(id)
732	                    ? repository.numberInPeriod(id, cid, LocalDate.parse(found.date()))
733	                    : repository.number(id, cid);
734	            repository.openedBy(id, cid, by);
735	            openedBy = by;
736	        }
737	        // Settling (or approving) fixes the claim's due as it is now: the figure its last statement bound it to
738	        // (a PENDING claim's is live), else its live due ('n/a' when its grade has no rate, which stays live), with its late charge frozen in.
739	        String due = null;
740	        String tail = event.equals("CLAIM_REJECTED") ? " reason=" + why : "";
741	        if (to.equals("SETTLED")) {
742	            BigDecimal now = repository.dueNow(id, found);
743	            repository.settleDue(id, cid, now);
744	            due = ClaimRepository.dueOf(now);
745	            tail = " due=" + (due == null ? "n/a" : due);
746	        }
