748	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), to,
749	                number, due, openedBy, found.stated(), found.statedDue(), found.corrects(), found.dueBy(),
750	                found.statedNa(), found.deferredUntil(), found.deferred());
751	        audit.record(event + " sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
752	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(number) + tail);
753	        rollup.record(id, by, before);
754	        return changed;
