461	/** Close a period: fix its due-total as shown now (the dues now, late charges included, of the counting claims dated in it, a person's
462	 *  open (OPEN or PENDING) claims dated within one of their holds left out unless bound by a statement,
463	 *  skipping those with none), so later changes to rates do not alter it; and each person's due-total for it
464	 *  likewise, for every person on the sheet (0.00 for one with nothing in it). */
465	public class ClosePeriod {
466	    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
467	            ServerHttpConnection connection, PeriodRepository repository, ClaimRepository claims, PersonRepository people, Audit audit,
468	            Out<Period> period) throws BadRequestException {
469	        String by = CurrentUser.require(connection);
470	        String id = sheetId == null ? "" : sheetId.trim();
471	        if (!repository.lockSheet(id)) {
472	            throw new BadRequestException("no such sheet");
473	        }
474	        Period found = repository.find(id, periodName == null ? "" : periodName.trim());
475	        if (found == null) {
476	            throw new BadRequestException("no such period");
477	        }
478	        if (found.closed()) {
479	            throw new BadRequestException("the period " + found.name() + " is already closed");
480	        }
481	        LocalDate from = LocalDate.parse(found.from());
482	        LocalDate to = LocalDate.parse(found.to());
483	        Map<Long, List<Hold>> holds = people.holds(id);
484	        BigDecimal total = BigDecimal.ZERO.setScale(2);
485	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
486	        for (Person p : people.list(id)) personTotals.put(p.id(), BigDecimal.ZERO.setScale(2));
487	        for (Claim c : claims.list(id)) {
488	            LocalDate on = LocalDate.parse(c.date());
489	            if (!c.counts(holds.getOrDefault(c.personId(), List.of())) || on.isBefore(from) || on.isAfter(to)) continue;
490	            BigDecimal now = claims.dueNow(id, c);
491	            if (now != null) {
492	                total = total.add(now);
493	                personTotals.merge(c.personId(), now, BigDecimal::add);
494	            }
495	        }
496	        String shown = total.setScale(2).toPlainString();
497	        repository.close(id, found.id(), total, personTotals);
498	        audit.record("PERIOD_CLOSED sheet=" + id + " by=" + by + " period=" + found.name() + " total=" + shown);
499	        period.set(new Period(found.id(), found.name(), found.from(), found.to(), true, shown, personTotals.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
500	                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new))));
501	    }
502	}
