707	/** Take a person's statement: record their due-total now, and bind each claim of theirs that counts (a
708	 *  person's open (OPEN or PENDING) claims dated within a hold do not, unless already bound) to the figure it has now (a settled claim keeps its frozen due); a
709	 *  claim with no figure because the rate that would apply to it has ended is bound to n/a; a
710	 *  claim that does not count is unbound (live again). A late charge is never bound: it keeps following
711	 *  the sheet's today. The due-total is as shown: the sum of the counting claims' dues now (late charges
712	 *  included), skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today
713	 *  is in force then and no counting claim has a fixed figure or a due (at the grade it was claimed under); at
714	 *  most the sheet's cap. */
715	public class TakeStatement {
716	    public void take(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
717	            ServerHttpConnection connection, PersonRepository people, ClaimRepository claims,
718	            SheetRepository sheets, SettingsRepository settings, Audit audit, Rollup rollup, Out<Person> person) throws BadRequestException {
719	        String by = CurrentUser.require(connection);
720	        String id = sheetId == null ? "" : sheetId.trim();
721	        long pid;
722	        try {
723	            pid = Long.parseLong(personId == null ? "" : personId.trim());
724	        } catch (NumberFormatException e) {
725	            throw new BadRequestException("no such person");
726	        }
727	        Person found = people.find(id, pid);
728	        if (found == null) {
729	            throw new BadRequestException("no such person");
730	        }
731	        LocalDate today = sheets.today(id);
732	        Rollup.Snapshot before = rollup.take(id);
733	        BigDecimal total = BigDecimal.ZERO.setScale(2);
734	        boolean fixed = false;
735	        int count = 0;
736	        for (Claim c : claims.ofPerson(id, pid)) {
737	            if (!c.counts(found.holds())) {
738	                claims.bind(id, c.id(), false, null, false);
739	                continue;
740	            }
741	            count++;
742	            fixed |= c.fixed();
743	            // The claim is bound to its figure; its late charge is not bound, but counts in the due-total.
744	            BigDecimal figure = claims.figure(id, c);
745	            BigDecimal now = claims.dueNow(id, c);
746	            if (now != null) {
747	                total = total.add(now);
748	                fixed = true;
749	            }
750	            // With no figure because the rate that would apply has ended (or it is bound to n/a already),
751	            // it is bound to n/a: it stays n/a even once a later rate is in force on its date.
752	            boolean na = figure == null && ((c.bound() && c.statedNa()) || claims.rateEnded(id, c));
753	            claims.bind(id, c.id(), true, figure, na);
754	        }
755	        String dueTotal = fixed || claims.rated(id, pid, today) ? SettingsRepository.capped(total, settings.cap(id)).setScale(2).toPlainString() : "n/a";
756	        people.stated(id, pid, dueTotal, today);
757	        audit.record("STATEMENT sheet=" + id + " by=" + by + " name=" + found.name() + " due-total=" + dueTotal
758	                + " claims=" + count);
759	        rollup.record(id, by, before);
760	        person.set(people.find(id, pid));
761	    }
762	}
