764	/** The sheet's figures as shown: each person's claimed, due-total and overdue-total, and the sheet's
765	 *  claimed-total, due-total and overdue-total. A change takes them before it writes, then after its own audit lines records one ROLLUP
766	 *  line per person whose figures moved (people in the order they were added; a new person counts as
767	 *  moved), then a TOTALS line when the sheet's totals moved. */
768	@Service
769	public class Rollup {
770	    /** A person's figures: claimed (two decimals), due-total (two decimals, or 'n/a') and overdue-total
771	     *  (two decimals: the sum of the dues now of their counting claims that are overdue, skipping those with none). */
772	    record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
773	        boolean same(Figures other) {
774	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
775	                    && overdueTotal.equals(other.overdueTotal);
776	        }
777	    }
778	    /** The figures of a sheet at one moment, people by id in the order they were added. */
779	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
780	    }
781	    private final PersonRepository people;
782	    private final ClaimRepository claims;
783	    private final SheetRepository sheets;
784	    private final SettingsRepository settings;
785	    private final Audit audit;
786	    public Rollup(PersonRepository people, ClaimRepository claims, SheetRepository sheets, SettingsRepository settings,
787	            Audit audit) {
788	        this.settings = settings;
789	        this.people = people;
790	        this.claims = claims;
791	        this.sheets = sheets;
792	        this.audit = audit;
793	    }
794	    /** The sheet's figures now. A person's due-total is the sum of their counting claims' dues now (late charges included),
795	     *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
796	     *  then and no counting claim keeps a fixed figure or has a due (at the grade it was claimed under). A due-total is at most the sheet's cap (an 'n/a' is not capped). The sheet's due-total skips 'n/a'. */
797	    public Snapshot take(String sheetId) {
798	        List<Person> everyone = people.list(sheetId);
799	        Map<Long, Figures> figures = new LinkedHashMap<>();
800	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
801	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
802	        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
803	        if (!everyone.isEmpty()) {
804	            LocalDate today = sheets.today(sheetId);
805	            List<Claim> all = claims.list(sheetId);
806	            BigDecimal cap = settings.cap(sheetId);
807	            for (Person p : everyone) {
808	                BigDecimal claimed = BigDecimal.ZERO.setScale(2);
809	                BigDecimal due = BigDecimal.ZERO.setScale(2);
810	                BigDecimal overdue = BigDecimal.ZERO.setScale(2);
811	                boolean fixed = false;
812	                for (Claim c : all) {
813	                    if (c.personId() != p.id() || !c.counts(p.holds())) continue;
814	                    claimed = claimed.add(new BigDecimal(c.amount()));
815	                    fixed |= c.fixed();
816	                    BigDecimal now = claims.dueNow(sheetId, c);
817	                    if (now != null) due = due.add(now);
818	                    if (now != null && c.open() && LocalDate.parse(c.dueBy()).isBefore(today)) overdue = overdue.add(now);
819	                    fixed |= now != null;
820	                }
821	                boolean shown = fixed || claims.rated(sheetId, p.id(), today);
822	                due = SettingsRepository.capped(due, cap);
823	                figures.put(p.id(), new Figures(p.name(), claimed.toPlainString(),
824	                        shown ? due.toPlainString() : "n/a", overdue.toPlainString()));
825	                claimedTotal = claimedTotal.add(claimed);
826	                if (shown) dueTotal = dueTotal.add(due);
827	                overdueTotal = overdueTotal.add(overdue);
828	            }
829	        }
830	        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString(), overdueTotal.toPlainString());
831	    }
832	    /** Record the lines for whatever figures moved since {@code before}. */
833	    public void record(String sheetId, String by, Snapshot before) {
834	        Snapshot after = take(sheetId);
835	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
836	            Figures now = e.getValue();
837	            if (now.same(before.people().get(e.getKey()))) continue;
838	            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
839	                    + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
840	        }
841	        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
842	                || !after.overdueTotal().equals(before.overdueTotal())) {
843	            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + after.claimedTotal()
844	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
845	        }
846	    }
847	}
