472	/** Bind the rate form: the grade must be A, B or C; the percent is required, 0.00 or more with up
473	 *  to two decimals (below 100000); a from-date is yyyy-mm-dd, and blank means from the beginning of time; a to-date is yyyy-mm-dd, not before the from-date, and blank means
474	 *  no end. */
475	public class ValidateRate {
476	    private static final Set<String> GRADES = Set.of("A", "B", "C");
477	    private static final Pattern PCT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?|\\.\\d{1,2}");
478	    public void validate(@RequestBody RateRequest request, Out<RateInput> rate) throws BadRequestException {
479	        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
480	        String pct = request == null || request.pct() == null ? "" : request.pct().trim();
481	        String from = request == null || request.from() == null ? "" : request.from().trim();
482	        String to = request == null || request.to() == null ? "" : request.to().trim();
483	        if (!GRADES.contains(grade)) {
484	            throw new BadRequestException("grade must be A, B or C");
485	        }
486	        if (pct.isEmpty()) {
487	            throw new BadRequestException("rate is required");
488	        }
489	        if (!PCT.matcher(pct).matches()) {
490	            throw new BadRequestException("rate must be a percent of 0.00 or more with up to two decimals");
491	        }
492	        LocalDate on = null;
493	        if (!from.isEmpty()) {
494	            try {
495	                on = LocalDate.parse(from);
496	            } catch (DateTimeParseException e) {
497	                throw new BadRequestException("from-date must be yyyy-mm-dd");
498	            }
499	        }
500	        LocalDate until = null;
501	        if (!to.isEmpty()) {
