757	/**
758	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
759	 * so tests can assert side-effects by reading that file — the second test-assertion channel
760	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
761	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
762	 *
763	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
764	 * SYNC) so a test reads the record immediately.
765	 */
766	@Service
767	public class Audit {
768	    private final Path file;
769	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
770	        this.file = Path.of(path);
771	    }
772	    /** Append one audit record. Tests assert the exact line(s) in the file. */
773	    public synchronized void record(String entry) {
774	        try {
775	            Path parent = file.toAbsolutePath().getParent();
776	            if (parent != null) {
777	                Files.createDirectories(parent);
778	            }
779	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
780	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
781	        } catch (IOException e) {
782	            throw new UncheckedIOException(e);
783	        }
784	    }
785	    /** Remove the audit file. */
786	    public synchronized void clear() {
787	        try {
788	            Files.deleteIfExists(file);
789	        } catch (IOException e) {
790	            throw new UncheckedIOException(e);
791	        }
792	    }
793	}
