import { counts, fixedDue, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { settingOn, useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { hundredths, money, rateFor, sumDues, useRates } from './useRates';

/** Each person's due-total, by person id: the sum of the figures of their claims that count (open (OPEN or PENDING)
 *  claims dated within one of their holds left out unless a statement binds them; a settled claim's frozen due, else the figure their last statement
 *  bound it to, else its live due, with its late charge while overdue),
 *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
 *  then and no counting claim of theirs keeps a fixed figure or has a due (at the grade it was claimed under).
 *  A due-total is at most the sheet's cap in force on its today ('n/a' is not capped). */
export function useDueTotals(sheetId: string): Map<number, string> {
  const totals = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) totals.set(id, f.total);
  return totals;
}

/** Each person's excess, by person id: how far the sum of their figures is above the sheet's cap; 0.00 when
 *  it is not (or there is no cap, or their due-total is 'n/a'). */
export function useExcess(sheetId: string): Map<number, string> {
  const excess = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) excess.set(id, f.excess);
  return excess;
}

/** Each person's due-total held to the cap, and their excess over it. */
function useDueFigures(sheetId: string): Map<number, { total: string; excess: string }> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const settings = useSettings(sheetId).data;
  const holds = holdsById(people.data);
  const cap = settingOn(settings, 'cap', today.data?.today);
  const totals = new Map<number, { total: string; excess: string }>();
  for (const p of people.data ?? []) {
    const counting = (claims.data ?? []).filter((c) => c.personId === p.id && counts(c, holds, today.data?.today));
    const rated = rateFor(rates.data, p.grade, today.data?.today) !== undefined;
    const dues = counting.map((c) =>
      claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date), settings, today.data?.today));
    const shown = rated || counting.some((c) => fixedDue(c) !== null && fixedDue(c) !== 'n/a') || dues.some((d) => d !== 'n/a');
    const sum = sumDues(dues);
    const over = shown && cap !== null && hundredths(sum) > hundredths(cap);
    totals.set(p.id, {
      total: !shown ? 'n/a' : over ? cap : sum,
      excess: over ? money(hundredths(sum) - hundredths(cap)) : '0.00',
    });
  }
  return totals;
}
import { counts, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { rateFor, sumDues, useRates } from '../rates/useRates';
import { useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { usePeriods } from './usePeriods';

/** Each person's due-total for each period, by person id then period name: the figures of their claims
 *  that count whose date falls in it (a settled claim's frozen due, else the figure its last statement
 *  bound it to, else its live due, with its late charge while overdue), skipping those with none — the
 *  one fixed when the period was closed while it is closed (0.00 for a person added since). */
export function usePersonPeriodDueTotals(sheetId: string): Map<number, Map<string, string>> {
  const periods = usePeriods(sheetId);
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  const holds = holdsById(people.data);
  const totals = new Map<number, Map<string, string>>();
  for (const person of people.data ?? []) {
    const own = (claims.data ?? []).filter((c) => c.personId === person.id && counts(c, holds, today));
    const byPeriod = new Map<string, string>();
    for (const p of periods.data ?? []) {
      byPeriod.set(
        p.name,
        p.closed
          ? (p.personTotals[String(person.id)] ?? '0.00')
          : sumDues(
              own
                .filter((c) => p.from <= c.date && c.date <= p.to)
                .map((c) => claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(person, c.date), c.date), settings, today)),
            ),
      );
    }
    totals.set(person.id, byPeriod);
  }
  return totals;
}

/** Each period's due-total, by period name: the sum of the people's due-totals for it. */
export function usePeriodDueTotals(sheetId: string): Map<string, string> {
  const periods = usePeriods(sheetId);
  const perPerson = [...usePersonPeriodDueTotals(sheetId).values()];
  const totals = new Map<string, string>();
  for (const p of periods.data ?? []) {
    totals.set(p.name, sumDues(perPerson.map((byPeriod) => byPeriod.get(p.name) ?? '0.00')));
  }
  return totals;
}
import { counts, fixedDue, isDeferred, isOpen, useClaims, type Claim } from '../claims/useClaims';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { due, isCorrection, rateFor, sumDues, useRates, withCharge } from '../rates/useRates';
import { settingOn, useSettings, type Settings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';

/** Whether a claim is overdue: it is open (OPEN or PENDING), not deferred, and its due-by is before the sheet's today. */
export function isOverdue(c: Claim, today: string): boolean {
  return isOpen(c) && !isDeferred(c, today) && c.dueBy < today;
}

/** Whether a claim's live figures (its rate step and late charge) round half up: when the claim is
 *  dated before the sheet's policy date (blank meaning the sheet's today); else they round half to
 *  even. A correction rounds by the date of the claim it corrects (its person's claim with that
 *  number), not its own. Half to even until the settings and the sheet's today are loaded. */
export function roundsHalfUp(c: Claim, claims: Claim[] | undefined, settings: Settings | undefined, today: string | undefined): boolean {
  const policy = settings === undefined ? undefined : settings.policyDate ?? today;
  if (policy === undefined) return false;
  const corrected = c.corrects === null
    ? undefined
    : (claims ?? []).find((o) => o.personId === c.personId && o.number === c.corrects);
  return (corrected?.date ?? c.date) < policy;
}

/** A claim's due now: its figure (a settled claim's frozen due, else the one its last statement
 *  bound it to, else its floored live due), plus, while it is overdue, the sheet's late percent in force on
 *  the claim's date of
 *  that figure for every full 30 days it is overdue, rounded like a due. The charge is never bound by
 *  a statement: it follows the sheet's today until settling freezes it in. A correction (a negative
 *  amount) has no late charge. Just the figure until the settings and the sheet's today are loaded. */
export function dueNow(c: Claim, figure: string, settings: Settings | undefined, today: string | undefined, halfUp: boolean): string {
  if (settings === undefined || today === undefined || !isOverdue(c, today) || isCorrection(c.amount)) {
    return figure;
  }
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${c.dueBy}T00:00:00Z`)) / 86_400_000;
  return withCharge(figure, settingOn(settings, 'late-pct', c.date) ?? '0.00', Math.floor(days / 30), halfUp);
}

/** A claim's due now (see `dueNow`) from its fixed figure, else its live due at this rate (a
 *  two-decimal percent; undefined when none applies) and the floor in force on its date, every rounding by
 *  the claim's policy (see `roundsHalfUp`) — the other claims on the sheet are what a correction is looked up in.
 *  No floor until the settings are loaded. */
export function claimDueNow(c: Claim, claims: Claim[] | undefined, pct: string | undefined,
  settings: Settings | undefined, today: string | undefined): string {
  const up = roundsHalfUp(c, claims, settings, today);
  const floor = settings === undefined ? undefined : settingOn(settings, 'floor', c.date) ?? undefined;
  return dueNow(c, fixedDue(c) ?? due(c.amount, pct, floor, up), settings, today, up);
}

/** Each person's overdue figures, by person id: how many of their claims that count are overdue, and
 *  the sum of those claims' dues now (a stated claim's bound figure, else its live due, with its late
 *  charge), skipping
 *  those with none. Empty until the terms and the sheet's today are loaded. */
export function useOverdue(sheetId: string): Map<number, { count: number; total: string }> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  const holds = holdsById(people.data);
  const figures = new Map<number, { count: number; total: string }>();
  if (settings === undefined || today === undefined) return figures;
  for (const p of people.data ?? []) {
    const overdue = (claims.data ?? []).filter(
      (c) => c.personId === p.id && counts(c, holds, today) && isOverdue(c, today),
    );
    figures.set(p.id, {
      count: overdue.length,
      total: sumDues(overdue.map((c) =>
        claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date), settings, today))),
    });
  }
  return figures;
}
import type { Claim } from '../claims/useClaims';

/** The statuses the summary counts; no claim is PENDING today, so its count stays 0. */
export const STATUSES: string[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

/** How many of these claims have a status. */
export function countWithStatus(claims: readonly Claim[] | undefined, status: string): number {
  return (claims ?? []).filter((c) => c.status === status).length;
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/useClaims';
import { GRADES, usePeople } from '../people/usePeople';
import { usePeriodDueTotals } from '../periods/usePeriodDueTotals';
import { usePeriods } from '../periods/usePeriods';
import { useDueTotals } from '../rates/useDueTotals';
import { sumDues } from '../rates/useRates';
import { countWithStatus, STATUSES } from './statusCounts';

/** The sheet's summary, worked out from the same figures the lists show: per grade, how many people
 *  have it on the sheet's today (retired people left out) and their due-totals added up (skipping
 *  'n/a'); per period, its due-total; per status, how many claims have it. */
function Summary({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const periods = usePeriods(sheetId);
  const dueTotals = useDueTotals(sheetId);
  const periodTotals = usePeriodDueTotals(sheetId);
  const active = (people.data ?? []).filter((p) => !p.retiredFrom);
  return (
    <section data-testid="summary">
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = active.filter((p) => p.grade === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>
                  {sumDues(onGrade.map((p) => dueTotals.get(p.id) ?? 'n/a'))}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
