import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade's rate: a percent with two decimals, in force from its from-date (yyyy-mm-dd; null when it
 *  applies from the beginning of time) through its to-date (null when it has no end). */
export type Rate = { grade: string; pct: string; from: string | null; to: string | null };

export function ratesKey(sheetId: string) {
  return ['sheet', sheetId, 'rates'];
}

/** The sheet's rates, by grade then from-date (an undated rate first); a grade with no rate is not
 *  listed. */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: async () =>
      (await getJson<{ rates: Rate[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`)).rates,
  });
}

/** The rate (a two-decimal percent) for a grade in force on a date (yyyy-mm-dd): the one with the
 *  latest from-date on or before it, an undated rate applying from the beginning of time; undefined
 *  when none applies, or the date is after that rate's to-date. */
export function rateFor(rates: Rate[] | undefined, grade: string | undefined, on: string | undefined): string | undefined {
  if (on === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > on)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  if (found?.to != null && found.to < on) return undefined;
  return found?.pct;
}

/** A two-decimal number as a whole count of hundredths ("12.50" -> 1250, "-0.30" -> -30). */
export function hundredths(v: string): bigint {
  const t = v.trim();
  const negative = t.startsWith('-');
  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}

/** A whole count of hundredths as a two-decimal number (-30 -> "-0.30"). */
export function money(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
}

/** A due: an amount (two decimals) times a rate (a two-decimal percent), divided by 100, rounded
 *  half up (when `halfUp`) or half to even to two decimals, and at least the sheet's floor (two decimals; none while it is not
 *  loaded; a correction, a negative amount, has no floor); 'n/a' when there is no rate. Worked in
 *  whole numbers, so exact. */
export function due(amount: string, pct: string | undefined, floor: string | undefined, halfUp: boolean): string {
  if (pct === undefined) return 'n/a';
  let cents = percentOf(amount, pct, 1n, halfUp);
  if (floor !== undefined && !isCorrection(amount) && cents < hundredths(floor)) cents = hundredths(floor);
  return money(cents);
}

/** Whether an amount (two decimals) is a correction's: below zero. */
export function isCorrection(amount: string): boolean {
  return hundredths(amount) < 0n;
}

/** An amount (two decimals) times a rate (a two-decimal percent) times a whole number, divided by
 *  100, rounded half up (when `halfUp`, away from zero) or half to even, in hundredths (a negative amount rounds as its size does, then takes
 *  its sign back). */
function percentOf(amount: string, pct: string, times: bigint, halfUp: boolean): bigint {
  const signed = hundredths(amount) * hundredths(pct) * times; // in 1/1_000_000 of a unit
  const product = signed < 0n ? -signed : signed;
  const rest = product % 10000n;
  let cents = product / 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  return signed < 0n ? -cents : cents;
}

/** A figure (two decimals) with a late charge added on top: the late percent (two decimals) of the
 *  figure for each of `periods` full 30 days, rounded like a due; 'n/a' stays 'n/a'. */
export function withCharge(figure: string, latePct: string, periods: number, halfUp: boolean): string {
  if (figure === 'n/a' || periods <= 0) return figure;
  return money(hundredths(figure) + percentOf(figure, latePct, BigInt(periods), halfUp));
}

/** Dues added up, skipping 'n/a'. */
export function sumDues(dues: string[]): string {
  return money(dues.filter((d) => d !== 'n/a').reduce((sum, d) => sum + hundredths(d), 0n));
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { heldOn, type Hold } from '../people/usePeople';

/** A claim's status: DRAFT -> OPEN -> SETTLED; a clerk's settle above the clerk limit goes to PENDING
 *  instead, which a steward approves (SETTLED) or rejects (OPEN again); a DRAFT, OPEN or PENDING claim
 *  can become VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim: its amount with two decimals, its date (yyyy-mm-dd), its note, its status, its number on
 *  the sheet (given when it is opened: 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft and once void) and the due fixed when it was
 *  settled (null unless settled while its grade had a rate: its due is then live, from the rates), and
 *  who opened it (null until it is opened), whether its person's last statement bound it, and the figure
 *  it was bound to (null when not bound, or bound with no figure: its due then stays live), and, for a
 *  correction (a negative amount), the number of the settled claim of the same person it corrects, and
 *  its due-by (yyyy-mm-dd), fixed when it was created from the terms of its person's grade then (else the
 *  sheet's terms), and its status log: a line per status it has had, oldest first, as
 *  "<STATUS> by <user> on <date> due=<due>" with the sheet's today and its due at that moment, and whether
 *  its last statement bound it to n/a (the rate that would apply to it had ended: its due stays n/a), and
 *  the date it is deferred until (null when it was never deferred: see `isDeferred`). */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  statedNa: boolean;
  deferredUntil: string | null;
  log: string[];
};

/** Whether a claim is open: OPEN, or PENDING (handled like OPEN everywhere but its statement binding). */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** A claim's fixed figure: the due frozen when it was settled, else the one its last statement bound
 *  it to (a PENDING claim is not bound; 'n/a' when it bound it to n/a); null when its due is live. */
export function fixedDue(c: Claim): string | null {
  if (c.due !== null) return c.due;
  if (!isBound(c)) return null;
  return c.statedNa ? 'n/a' : c.statedDue;
}

/** Whether a claim is deferred now: it is OPEN and the date it is deferred until is after the sheet's
 *  today. Until today reaches that date it counts in no total, is not overdue and cannot be settled. */
export function isDeferred(c: Claim, today: string | undefined): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today !== undefined && today < c.deferredUntil;
}

/** Whether a claim counts toward claimed and every live total, given the people's holds by person id
 *  and the sheet's today: only open (OPEN or PENDING) and SETTLED claims do, and an open claim dated within
 *  one of its person's holds does not, unless a statement binds it, nor does a deferred one. */
export function counts(c: Claim, holds: ReadonlyMap<number, Hold[]>, today: string | undefined): boolean {
  return c.status === 'SETTLED'
    || (isOpen(c) && !isDeferred(c, today) && (isBound(c) || !heldOn(holds.get(c.personId), c.date)));
}

/** Whether its person's last statement binds a claim now: it was stated and is not PENDING. */
export function isBound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

export function claimsKey(sheetId: string) {
  return ['sheet', sheetId, 'claims'];
}

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: async () => {
      const res = await getJson<{ claims: Omit<Claim, 'log'>[]; logs: Record<string, string[]> }>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims`,
      );
      return res.claims.map((c): Claim => ({ ...c, log: res.logs[String(c.id)] ?? [] }));
    },
  });
}

/** The sum of the amounts of those of these claims that count (given the people's holds by person id and
 *  the sheet's today), with two decimals (added up in cents, so no rounding drift). */
export function claimed(claims: Claim[], holds: ReadonlyMap<number, Hold[]>, today: string | undefined): string {
  const cents = claims.filter((c) => counts(c, holds, today)).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person: `grade` is the one in force on the sheet's today, `grades` every grade they have been
 *  given, oldest first; `version` goes up by one each time they are saved. Their statements: how many have been
 *  taken, and the last one's due-total and date (null before the first); the date they are retired
 *  from (null when not retired); their holds, oldest first, and whether they have any (their open (OPEN or PENDING)
 *  claims dated within a hold, unless bound by a statement, then count in no live total). */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: GradeFrom[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retiredFrom: string | null;
  held: boolean;
  holds: Hold[];
};

/** One of a person's holds: from its from-date to its to-date (yyyy-mm-dd, both inclusive; a null
 *  from-date is the beginning of time, a null to-date open-ended). */
export type Hold = { from: string | null; to: string | null };

/** Whether any of these holds covers a date (yyyy-mm-dd). */
export function heldOn(holds: readonly Hold[] | undefined, on: string): boolean {
  return (holds ?? []).some((h) => (h.from === null || h.from <= on) && (h.to === null || h.to >= on));
}

/** One of a person's grades: in force from its from-date (yyyy-mm-dd; null for the first grade they
 *  were given, which applies from the beginning of time) until the next one's. */
export type GradeFrom = { grade: string; from: string | null };

/** The grade a person has on a date (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, on: string): string | undefined {
  let found: GradeFrom | undefined;
  for (const g of person?.grades ?? []) {
    if (g.from !== null && g.from > on) continue;
    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/** One of a person's patrons: another person on the same sheet, by id. */
export type Patron = { personId: number; patronId: number };

export const GRADES = ['A', 'B', 'C'] as const;

export function peopleKey(sheetId: string) {
  return ['sheet', sheetId, 'people'];
}

/** The sheet's people and the patrons they have named, as the store holds them. */
type PeopleBody = { people: Person[]; patrons: Patron[] };

function peopleBody(sheetId: string): Promise<PeopleBody> {
  return getJson<PeopleBody>(`/api/sheets/${encodeURIComponent(sheetId)}/people`);
}

/** Read the sheet's people from the store. */
export async function fetchPeople(sheetId: string): Promise<Person[]> {
  return (await peopleBody(sheetId)).people;
}

export function patronsKey(sheetId: string) {
  return [...peopleKey(sheetId), 'patrons'];
}

/** Every patron named on the sheet, re-read from the store. */
export function usePatrons(sheetId: string) {
  return useQuery({
    queryKey: patronsKey(sheetId),
    queryFn: async () => (await peopleBody(sheetId)).patrons,
  });
}

/** These people's holds, by person id. */
export function holdsById(people: Person[] | undefined): Map<number, Hold[]> {
  return new Map((people ?? []).map((p) => [p.id, p.holds ?? []]));
}

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery({
    queryKey: peopleKey(sheetId),
    queryFn: () => fetchPeople(sheetId),
  });
}

